// 只有实际本人当面公开才建立条款知情；不把关系、死亡消息或全局账可读当作已经获知。
#include "bequest_disclosure_source.hpp"
#include "family_continuation_people4.hpp"
#include "resident/domains/interaction/face_to_face_contact.hpp"
#include <algorithm>
#include <tuple>
namespace hanmo::resident { namespace {
// 同tick来源始终取Common事实序，不能按数字ID或当前人物猜过去。
bool before(const CommonStore& c,const StableId& a,const StableId& b){const auto& ids=c.state().facts.order();auto x=std::find(ids.begin(),ids.end(),a),y=std::find(ids.begin(),ids.end(),b);return x!=ids.end()&&y!=ids.end()&&x<y;}
// 原条款只允许原遗赠人向该唯一受益人公开，不扩大到旁人或另一份声明。
Status binding(const CommonStore& c,const FamilyBequestState& state,const BequestDisclosureSource& s,Integer version,const FamilyContinuationPeopleRead4* people){if(version!=1&&version!=2)return common_failure("FamilyInheritanceVersionRequired",{},ErrorKind::unsupported_capability);if(version==1&&s.occurred_at)return common_failure("InheritanceProfileMismatch",{},ErrorKind::internal);if(version==2){if(!people||!people->bound_to(c)||!s.occurred_at)return common_failure("InheritancePeople4Required",{},ErrorKind::unsupported_capability);auto now=people->read_current_moment();if(!now.ok)return {false,{},now.error};auto cmp=compare_world_moments(*s.occurred_at,now.value);if(!cmp.ok)return {false,{},cmp.error};if(s.tick!=s.occurred_at->half_day_tick||cmp.value>0)return common_failure("BequestDisclosureTimeMismatch",{},ErrorKind::internal);}
const auto* d=state.declarations.find(s.declaration_id);const auto* h=c.state().facts.find(s.declaration_id);if(!d||!h||h->kind!="family_bequest_declaration"||h->domain!="family_bequest")return common_failure("UnknownBequestDeclaration",s.declaration_id);const auto& t=d->source.terms;if(t.donor_actor_id!=s.donor_actor_id||t.beneficiary_actor_id!=s.beneficiary_actor_id||s.donor_actor_id==s.beneficiary_actor_id)return common_failure("BequestDisclosurePartiesMismatch");if(s.world_id!=c.state().identity.world_id||s.scenario_id!=c.state().metadata.scenario_id||s.tick<d->source.tick||(version==1&&s.tick>c.tick())||s.revision<d->source.revision||s.revision>c.revision())return common_failure("BequestDisclosureSourceMismatch");return common_success();}
// 快照逐字段比较原实际上下文，字段展示顺序不构成另一场接触。
bool same_context(const InteractionContext& a,const InteractionContext& b){return std::tie(a.place_id,a.provider_actor_id,a.role_id,a.kind,a.encounter_id,a.input_error)==std::tie(b.place_id,b.provider_actor_id,b.role_id,b.kind,b.encounter_id,b.input_error);}
}
// 来源只冻结本命令公开的确切条款及原节点，不复制另一套遗赠资产账。
bool bequest_disclosure_source_equal(const BequestDisclosureSource& a,const BequestDisclosureSource& b){if(a.occurred_at.has_value()!=b.occurred_at.has_value())return false;if(a.occurred_at){auto same=compare_world_moments(*a.occurred_at,*b.occurred_at);if(!same.ok||same.value!=0)return false;}return std::tie(a.declaration_id,a.donor_actor_id,a.beneficiary_actor_id,a.dialogue_id,a.node_id,a.node_kind,a.session_id,a.scenario_id,a.world_id,a.tick,a.revision)==std::tie(b.declaration_id,b.donor_actor_id,b.beneficiary_actor_id,b.dialogue_id,b.node_id,b.node_kind,b.session_id,b.scenario_id,b.world_id,b.tick,b.revision)&&same_context(a.context,b.context);}
// 当前只有say/choice场所节点能公开；waiting/action/trade不能兼作一次新的当面送达。
Outcome<BequestDisclosureQuote> preview_bequest_disclosure(const CommonStore& c,const FamilyBequestState& state,const InteractionState& meeting,const InteractionCatalog& catalog,const InteractionAccess& access,const StableId& id,Integer version,const FamilyContinuationPeopleRead4* people){const auto* d=state.declarations.find(id);if(!d)return {false,{},common_failure("UnknownBequestDeclaration",id).error};const auto& t=d->source.terms;if(t.donor_actor_id!=c.state().metadata.player_actor_id)return {false,{},common_failure("BequestDonorAuthorityRequired").error};for(const auto& actor:{t.donor_actor_id,t.beneficiary_actor_id}){const auto* a=c.actor(actor);if(!a||!a->alive||!a->available)return {false,{},common_failure("BequestLivingPartiesRequired",actor).error};}for(const auto& row:state.revocations.rows())if(row.second.declaration_id==id)return {false,{},common_failure("BequestAlreadyRevoked",id).error};auto proof=preview_authored_node_source(c,meeting,catalog,access,t.donor_actor_id,t.beneficiary_actor_id);if(!proof.ok)return {false,{},proof.error};if(proof.value.node_kind!="say"&&proof.value.node_kind!="choice")return {false,{},common_failure("BequestDisclosureConversationRequired").error};BequestDisclosureQuote q;q.meeting=proof.value;auto& s=q.source;if(version==2){if(!people||!people->bound_to(c))return {false,{},common_failure("InheritancePeople4Required",{},ErrorKind::unsupported_capability).error};auto now=people->read_current_moment();if(!now.ok)return {false,{},now.error};s.occurred_at=std::move(now.value);for(const auto* actor:{&t.donor_actor_id,&t.beneficiary_actor_id}){auto presence=people->read_current_presence(*actor);if(!presence.ok)return {false,{},presence.error};if(!presence.value.alive)return {false,{},common_failure("BequestLivingPartiesRequired",*actor).error};}}s.declaration_id=id;s.donor_actor_id=t.donor_actor_id;s.beneficiary_actor_id=t.beneficiary_actor_id;s.dialogue_id=proof.value.dialogue_id;s.node_id=proof.value.node_id;s.node_kind=proof.value.node_kind;s.session_id=proof.value.session_id;s.context=proof.value.context;s.world_id=c.state().identity.world_id;s.scenario_id=c.state().metadata.scenario_id;s.tick=s.occurred_at?s.occurred_at->half_day_tick:c.tick();s.revision=c.revision();auto valid=binding(c,state,s,version,people);return valid.ok?Outcome<BequestDisclosureQuote>{true,std::move(q),{}}:Outcome<BequestDisclosureQuote>{false,{},valid.error};}
// 正式公开前原当前会话和完整来源都必须仍一致；纯读不会创建关系、消息或资产。
Status revalidate_bequest_disclosure(const CommonStore& c,const FamilyBequestState& state,const InteractionState& meeting,const InteractionCatalog& catalog,const InteractionAccess& access,const BequestDisclosureQuote& quote,Integer version,const FamilyContinuationPeopleRead4* people){auto valid=revalidate_authored_node_source(c,meeting,catalog,access,quote.meeting);if(!valid.ok)return valid;auto fresh=preview_bequest_disclosure(c,state,meeting,catalog,access,quote.source.declaration_id,version,people);if(!fresh.ok)return {false,{},fresh.error};return bequest_disclosure_source_equal(quote.source,fresh.value.source)?common_success():common_failure("StaleBequestDisclosure");}
// 过去公开必须晚于声明且早于撤回/任一方死亡；后来撤回可保知识却阻止受领。
Status validate_bequest_disclosure_source(const CommonStore& c,const FamilyBequestState& state,const FamilyDeathState& deaths,const InteractionCatalog& catalog,const FamilyBequestPlayerRead& player,const BequestDisclosureSource& s,const StableId& fact,Integer version,const FamilyContinuationPeopleRead4* people){auto valid=binding(c,state,s,version,people);if(!valid.ok)return valid;if(!before(c,s.declaration_id,fact)||!player)return common_failure("BequestDisclosureHistoryRequired");auto historical=player(s.tick,fact);if(!historical.ok)return {false,{},historical.error};if(historical.value!=s.donor_actor_id)return common_failure("BequestDisclosureDonorMismatch");for(const auto& row:state.revocations.rows())if(row.second.declaration_id==s.declaration_id&&!before(c,fact,row.first))return common_failure("BequestDisclosureAfterRevocation");for(const auto& actor:{s.donor_actor_id,s.beneficiary_actor_id}){if(version==2){if(!people||!people->bound_to(c,deaths))return common_failure("InheritancePeople4Required",{},ErrorKind::unsupported_capability);auto alive=people->read_presence_before_original_fact(actor,s.tick,{"family_inheritance","family_bequest_disclosed",fact});if(!alive.ok)return {false,{},alive.error};if(!alive.value.alive)return common_failure("BequestDisclosureAfterDeath",actor);}else{const auto* death=family_death_for_actor(deaths,actor);if(death&&(s.tick>death->death_tick||!before(c,fact,death->cause_fact_id)))return common_failure("BequestDisclosureAfterDeath",actor);}}
    if(s.session_id.empty()||!face_to_face_contact_context_valid(s.context)||s.context.provider_actor_id!=s.beneficiary_actor_id||!catalog.common||!catalog.common->places.find(s.context.place_id))return common_failure("InvalidBequestDisclosureContext");const DialogueDefinition* dialogue=nullptr;for(const auto& row:catalog.dialogues)if(row.id==s.dialogue_id)dialogue=&row;if(!dialogue||dialogue->context_role!=s.context.role_id)return common_failure("InvalidBequestDisclosureDialogue");const DialogueNode* node=nullptr;for(const auto& row:dialogue->nodes)if(row.id==s.node_id)node=&row;if(!node||(s.node_kind!="say"&&s.node_kind!="choice")||node->kind!=s.node_kind)return common_failure("InvalidBequestDisclosureNode");if(s.context.kind){bool found=false;for(const auto& topic:catalog.regional_actor_topics)if(topic.actor_id==s.beneficiary_actor_id&&topic.dialogue_id==s.dialogue_id)found=true;if(!found)return common_failure("InvalidBequestDisclosureNarrative");}else {const auto* role=catalog.common->roles.find(s.context.role_id);if(!role||role->place_id!=s.context.place_id)return common_failure("InvalidBequestDisclosureRole");}return common_success();
}
}
